ST.xhtml:p:
RStart(CLK := g_bPlcStartBuffer);
RPause(CLK := g_bPlcPauseBuffer);
RReset(CLK := g_bPlcResetBuffer);

IF RStart.Q THEN
  g_boCustomStart:=TRUE;
  g_boCustomPause:=FALSE;
  g_boCustomReset:=FALSE;
  nDealyState := 10;
END_IF;
IF RPause.Q THEN
  g_boCustomStart:=FALSE;
  g_boCustomPause:=TRUE;
  g_boCustomReset:=FALSE;
  nDealyState := 10;
END_IF;
IF RReset.Q THEN
  g_boCustomStart:=FALSE;
  g_boCustomPause:=FALSE;
  g_boCustomReset:=TRUE;
  nDealyState := 10;
END_IF;

CASE nDealyState OF
  0:
    nDealyState := 0;
    Ton_Dealy(IN :=FALSE);
  10:
    Ton_Dealy(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(300)));
    IF Ton_Dealy.Q THEN
      g_boCustomStart:=FALSE;
      g_boCustomPause:=FALSE;
      g_boCustomReset:=FALSE;
      nDealyState := 0;
    END_IF;

END_CASE;
